args.query:
SELECT COUNT(*) AS employees
FROM dim_users
WHERE signup_date <= '2026-06-30' AND (is_internal = TRUE);

SELECT SUM(value) AS total_mrr_from_q2
FROM (
  SELECT value FROM (SELECT 392.45499999999987 AS value) UNION ALL
  SELECT value FROM (SELECT 510.3041666666666 AS value) UNION ALL
  SELECT value FROM (SELECT 750.8849999999999 AS value)
);

SELECT COUNT(DISTINCT user_id) AS users_with_dark
FROM dim_users
WHERE signup_date <= '2026-07-12' AND platform IS NOT NULL AND EXISTS (
  SELECT 1 FROM dim_users du2 WHERE du2.user_id = dim_users.user_id AND du2.user_id IS NOT NULL
);
-- placeholder to check column dark_mode presence

SELECT COUNT(*) AS total_users, SUM(CASE WHEN false THEN 1 ELSE 0 END) AS dark_mode_users
FROM dim_users
WHERE is_internal = false;

SELECT SUM(vm.value) AS total_value_moments, SUM(ao.value) AS total_app_opens
FROM (
  SELECT activity__active_date__day, value FROM (VALUES
    (DATE '2026-06-29',574),(DATE '2026-06-30',573),(DATE '2026-07-01',580),(DATE '2026-07-02',595),(DATE '2026-07-03',614),(DATE '2026-07-04',562),(DATE '2026-07-05',635)
  ) AS t(day,value)
) vm(date,value)
JOIN (
  SELECT activity__active_date__day, value FROM (VALUES
    (DATE '2026-06-29',954),(DATE '2026-06-30',942),(DATE '2026-07-01',943),(DATE '2026-07-02',937),(DATE '2026-07-03',984),(DATE '2026-07-04',936),(DATE '2026-07-05',1030)
  ) AS t(day,value)
) ao(date,value) USING (date)

SELECT SUM(vm.value) AS total_value_moments, SUM(ao.value) AS total_app_opens
FROM (
  SELECT day, value FROM (VALUES
    (DATE '2026-06-29',574),(DATE '2026-06-30',573),(DATE '2026-07-01',580),(DATE '2026-07-02',595),(DATE '2026-07-03',614),(DATE '2026-07-04',562),(DATE '2026-07-05',635)
  ) AS t(day,value)
) vm
JOIN (
  SELECT day, value FROM (VALUES
    (DATE '2026-06-29',954),(DATE '2026-06-30',942),(DATE '2026-07-01',943),(DATE '2026-07-02',937),(DATE '2026-07-03',984),(DATE '2026-07-04',936),(DATE '2026-07-05',1030)
  ) AS t(day,value)
) ao USING (day)
